    private void formWindowOpened(java.awt.event.WindowEvent evt) {//GEN-FIRST:event_formWindowOpened
        db_conn d=new db_conn();
        try
        {   l.addItem("Select Year");
            d.query="select Year from payment";
            
            ResultSet rs=d.select();
            
            
            while(rs.next())
            {
                
                l.addItem(""+rs.getInt("Year"));
            }
        }
        catch(NullPointerException e){
               JOptionPane.showMessageDialog(null,""+d.error());
        }
        catch(SQLException e){
            JOptionPane.showMessageDialog(null,e);
        }
    }//GEN-LAST:event_formWindowOpened

    private void lActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_lActionPerformed
    db_conn d=new db_conn();
        try
        {
            String y=""+l.getSelectedItem();
            if(!y.equals("Select Year"))
            {
                d.query="select * from payment where Year=?";
                d.a.add(y);
                
                ResultSet rs=d.select();
            if(rs.next()){
                jan.setText(String.valueOf(rs.getInt(2)));
                feb.setText(String.valueOf(rs.getInt(3)));
                march.setText(String.valueOf(rs.getInt(4)));
                april.setText(String.valueOf(rs.getInt(5)));
                may.setText(String.valueOf(rs.getInt(6)));
                june.setText(String.valueOf(rs.getInt(7)));
                july.setText(String.valueOf(rs.getInt(8)));
                aug.setText(String.valueOf(rs.getInt(9)));
                sep.setText(String.valueOf(rs.getInt(10)));
                oct.setText(String.valueOf(rs.getInt(11)));
                nov.setText(String.valueOf(rs.getInt(12)));
                dec.setText(String.valueOf(rs.getInt(13)));
            
                int temp=rs.getInt(2)+rs.getInt(3)+rs.getInt(4)+rs.getInt(5)+rs.getInt(6)+rs.getInt(7)+rs.getInt(8)+rs.getInt(9)+rs.getInt(10)+rs.getInt(11)+rs.getInt(12)+rs.getInt(13);
                t.setText(String.valueOf(temp));
            }
            else{
               JOptionPane.showMessageDialog(null,"No Previus Record"); 
            }
            }
        }
       catch(NullPointerException e){
            JOptionPane.showMessageDialog(null,""+d.error());
        }
        catch(SQLException e){
            JOptionPane.showMessageDialog(null,e);
        }
    }//GEN-LAST:event_lActionPerformed

